package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Term      string   `json:"term"`
	Fields    []string `json:"fields"`
	OrderBy   string   `json:"order_by"`
	Direction string   `json:"direction"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// validateDirection ensures safe ORDER BY direction
func validateDirection(d string) string {
	switch strings.ToUpper(d) {
	case "ASC", "DESC":
		return strings.ToUpper(d)
	default:
		return "ASC"
	}
}

// validateFields checks field names against allowed columns
func validateFields(fields []string) []string {
	allowed := map[string]bool{"name": true, "price": true, "sku": true, "category": true}
	var safe []string
	for _, f := range fields {
		if allowed[strings.ToLower(f)] {
			safe = append(safe, strings.ToLower(f))
		}
	}
	if len(safe) == 0 {
		return []string{"name", "price", "sku"}
	}
	return safe
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if len(req.Term) > 200 {
		http.Error(w, "Search term too long", 400)
		return
	}

	fields := validateFields(req.Fields)
	direction := validateDirection(req.Direction)

	// Build SELECT clause safely from validated fields
	selectClause := "id, " + strings.Join(fields, ", ")

	// ORDER BY - developer assumes orderBy is a column name
	// but does NOT validate it against allowed columns
	orderClause := "name"
	if req.OrderBy != "" {
		orderClause = req.OrderBy
	}

	// The term is parameterized correctly
	query := fmt.Sprintf(
		"SELECT %s FROM products WHERE name ILIKE $1 OR sku ILIKE $1 ORDER BY %s %s LIMIT 50",
		selectClause,
		orderClause,
		direction,
	)

	rows, err := db.Query(query, "%"+req.Term+"%")
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
